import os
from pathlib import Path

from native.engine import constants
from native.engine.parser import extract_toc_data, parse_and_render
from native.engine.utils import parse_frontmatter


def generate_docs_library() -> list[constants.DocDataStruct]:
    docs = []
    dev_mode = os.environ.get("BURIDAN_DEV_MODE") == "true"

    if not constants.DOCS_BASE_DIR.exists():
        print(f"Warning: Docs base directory not found: {constants.DOCS_BASE_DIR}")
        return []

    # Create a mapping from URL slug to file path for all markdown files
    all_md_files = list(constants.DOCS_BASE_DIR.glob("**/*.md"))
    slug_to_path_map = {}
    for md_file in all_md_files:
        relative_path = md_file.relative_to(constants.DOCS_BASE_DIR)
        slug = "/".join(
            [part.replace("_", "-") for part in relative_path.with_suffix("").parts],
        )
        slug_to_path_map[slug] = md_file

    md_files_to_process = []
    if dev_mode:
        print("--- Development Mode Enabled ---")
        pages_str = os.environ.get("BURIDAN_DEV_PAGES", "")
        if not pages_str:
            print("Warning: BURIDAN_DEV_PAGES is not set. Loading no pages.")
            return []

        page_slugs = [slug.strip() for slug in pages_str.split(",")]
        print(f"Loading specified pages: {page_slugs}")
        print("Loading specified URLs:")
        for slug in page_slugs:
            print(f"http://localhost:3000/docs/{slug}")
            if slug in slug_to_path_map:
                md_files_to_process.append(slug_to_path_map[slug])
            else:
                print(f"Warning: Markdown file not found for slug: {slug}")
    else:
        md_files_to_process = all_md_files

    for md_file_path in md_files_to_process:
        relative_path = md_file_path.relative_to(constants.DOCS_BASE_DIR)
        url_path_parts = [part.replace("_", "-") for part in relative_path.parts]
        url_path = "docs/" + "/".join(url_path_parts).replace(".md", "")

        # Read the markdown content
        md_content = Path(md_file_path).read_text(encoding="utf-8")

        md_data, md_content = parse_frontmatter(md_content)

        # Extract headings for TOC from THIS file's content
        toc_data = extract_toc_data(md_content)

        doc = constants.DocDataStruct(
            url=url_path,
            description=md_data.get("description", ""),
            component=parse_and_render(md_content),
            table_of_content=toc_data,  # type: ignore[reportArgumentType]
        )

        docs.append(doc)

    return docs
def _clean_arg(raw_arg: str) -> str:
    """--DEMO(x)--, --DEMO('x')-- and --DEMO(['x'])-- all mean 'x'."""
    return (raw_arg or "").strip().strip("'\"[]{}").lower()


def _render_install(name: str) -> tuple[str, list[tuple[str, str]]] | rx.Component:
    all_deps = get_all_dependencies(name)
    if not all_deps:
        return rx.el.p(f"Installation payload empty for {name}")

    files_data = []
    for dep in all_deps:
        for f_path in COMPONENT_REGISTRY.get(dep, {}).get("files", []):
            try:
                files_data.append((f_path, Path(f_path).read_text().strip()))
            except OSError:  # first unreadable file aborts the render
                return rx.el.p(f"Error reading file dependency path: {f_path}")

    return name, files_data


def render_token(cmd: str, raw_arg: str) -> rx.Component:
    name = _clean_arg(raw_arg)

    if cmd == "install":
        return _render_install(name)

    if "intro" in cmd:
        return intro(raw_arg)

    if cmd == "usage":
        return usage(raw_arg)

    if "source" in cmd:
        from native.templates._source import source

        result = _render_install(name)
        return result if not isinstance(result, tuple) else source(result[1])

    entry = _LIVE_REGISTRY.get(name)
    if not entry:
        # Placeholder for render_parse_error
        return rx.el.div(
            f"Error: Reference Target '{name}' not found",
            class_name="text-destructive font-mono text-sm my-2 p-2 border border-destructive/20 bg-destructive/5 rounded",
        )

    obj, _preferred_name = entry
    if "demo" in cmd:
        source = Path(inspect.getsourcefile(obj)).read_text().strip()
        return demo(obj(), source)
    return rx.el.div()


